// ── Hilfsfunktionen ──
const now = Date.now();
const msPerDay = 86400000;
const isThisWeek = (dateStr) => {
  if (!dateStr) return false;
  return (now - new Date(dateStr).getTime()) < 7 * msPerDay;
};

// ── Content Pieces ──
let pieces = [];
try { pieces = $('Fetch Content Pieces').first().json?.list ?? []; } catch(e) {}
const piecesThisWeek = pieces.filter(p => isThisWeek(p.created_at ?? p.CreatedAt));
const byStatus = {};
for (const p of piecesThisWeek) {
  const s = p.status ?? 'unknown';
  byStatus[s] = (byStatus[s] ?? 0) + 1;
}

// Top Pieces (published zuerst, dann approved, dann draft)
const statusOrder = { published: 0, approved: 1, review: 2, draft: 3, idea: 4 };
const topPieces = [...piecesThisWeek]
  .sort((a, b) => (statusOrder[a.status] ?? 9) - (statusOrder[b.status] ?? 9))
  .slice(0, 5);

// ── Pipeline Jobs ──
let pipelineJobs = [];
try { pipelineJobs = $('Fetch Pipeline Jobs').first().json?.list ?? []; } catch(e) {}
const jobsThisWeek = pipelineJobs.filter(j => isThisWeek(j.created_at ?? j.CreatedAt));
const jobsByStatus = {};
const jobsByStage = {};
for (const j of jobsThisWeek) {
  const s = j.status ?? 'unknown';
  const stage = j.stage ?? 'unknown';
  jobsByStatus[s] = (jobsByStatus[s] ?? 0) + 1;
  jobsByStage[stage] = (jobsByStage[stage] ?? 0) + 1;
}
const jobsDone = jobsByStatus['completed'] ?? jobsByStatus['done'] ?? 0;
const jobsFailed = jobsByStatus['failed'] ?? jobsByStatus['error'] ?? 0;
const jobsTotal = jobsThisWeek.length;
const successRate = jobsTotal > 0 ? Math.round(jobsDone / jobsTotal * 100) : 0;

// Bottleneck: Stage mit meisten Fehlern
const failedJobs = jobsThisWeek.filter(j => ['failed','error'].includes(j.status));
const failedByStage = {};
for (const j of failedJobs) {
  const stage = j.stage ?? 'unknown';
  failedByStage[stage] = (failedByStage[stage] ?? 0) + 1;
}
const bottleneck = Object.entries(failedByStage).sort((a,b) => b[1]-a[1])[0];

// ── n8n Ausführungen ──
let executions = [];
try { executions = $('Fetch n8n Executions').first().json?.data ?? []; } catch(e) {}
const execThisWeek = executions.filter(e => isThisWeek(e.startedAt ?? e.created_at));
const execSuccess = execThisWeek.filter(e => e.status === 'success').length;
const execFailed = execThisWeek.filter(e => ['error','failed'].includes(e.status)).length;
const execRate = execThisWeek.length > 0 ? Math.round(execSuccess / execThisWeek.length * 100) : 0;

// Top Workflows nach Ausführungen
const wfCount = {};
for (const e of execThisWeek) {
  const wfName = e.workflowData?.name ?? e.workflowId ?? 'unbekannt';
  wfCount[wfName] = (wfCount[wfName] ?? 0) + 1;
}
const topWorkflows = Object.entries(wfCount).sort((a,b) => b[1]-a[1]).slice(0, 3);

// ── Content Opportunities ──
let opportunities = [];
try { opportunities = $('Fetch Content Opportunities').first().json?.list ?? []; } catch(e) {}
const newOpportunities = opportunities.filter(o => isThisWeek(o.created_at ?? o.CreatedAt));
const topOpportunities = newOpportunities.slice(0, 3);

// ── Gesamtbewertung ──
const contentScore = piecesThisWeek.length >= 5 ? '🟢' : piecesThisWeek.length >= 2 ? '🟡' : '🔴';
const pipelineScore = successRate >= 80 ? '🟢' : successRate >= 50 ? '🟡' : '🔴';
const n8nScore = execRate >= 90 ? '🟢' : execRate >= 70 ? '🟡' : '🔴';

// ── Report zusammenbauen ──
const kw = Math.ceil((new Date().getTime() - new Date(new Date().getFullYear(), 0, 1).getTime()) / (7 * msPerDay));
const dateStr = new Date().toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'Europe/Berlin' });

let report = `📊 *AIOS Weekly Summary — KW${kw}* (${dateStr})\n`;
report += `━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

// KPI-Überblick
report += `*KPIs auf einen Blick:*\n`;
report += `${contentScore} Content: ${piecesThisWeek.length} neue Pieces\n`;
report += `${pipelineScore} Pipeline: ${successRate}% Erfolgsrate (${jobsDone}/${jobsTotal} Jobs)\n`;
report += `${n8nScore} n8n: ${execRate}% Erfolgsrate (${execSuccess}/${execThisWeek.length} Runs)\n\n`;

// Content-Produktion
report += `*📝 Content-Produktion:*\n`;
if (piecesThisWeek.length === 0) {
  report += `• Keine neuen Pieces diese Woche\n`;
} else {
  const statusLabels = { published: 'Published', approved: 'Approved', review: 'In Review', draft: 'Draft', idea: 'Idee' };
  for (const [s, count] of Object.entries(byStatus)) {
    report += `• ${statusLabels[s] ?? s}: ${count}\n`;
  }
}
if (topPieces.length > 0) {
  report += `\n*Top Pieces:*\n`;
  for (const p of topPieces) {
    const icon = p.status === 'published' ? '✅' : p.status === 'approved' ? '🟢' : '📝';
    const title = (p.title ?? p.topic ?? 'Unbekannt').substring(0, 50);
    report += `${icon} ${title}\n`;
  }
}
report += `\n`;

// Pipeline-Gesundheit
report += `*⚙️ Pipeline-Gesundheit:*\n`;
if (jobsTotal === 0) {
  report += `• Keine Jobs diese Woche\n`;
} else {
  report += `• Gesamt: ${jobsTotal} | ✅ ${jobsDone} | ❌ ${jobsFailed}\n`;
  if (bottleneck) {
    report += `• 🚨 Bottleneck: Stage "${bottleneck[0]}" (${bottleneck[1]} Fehler)\n`;
  }
}
report += `\n`;

// n8n-Statistik
report += `*🔄 n8n-Aktivität:*\n`;
report += `• ${execThisWeek.length} Runs | ✅ ${execSuccess} | ❌ ${execFailed}\n`;
if (topWorkflows.length > 0) {
  report += `• Aktivste Workflows:\n`;
  for (const [name, count] of topWorkflows) {
    const shortName = name.substring(0, 35);
    report += `  - ${shortName}: ${count}x\n`;
  }
}
report += `\n`;

// Content-Chancen
if (newOpportunities.length > 0) {
  report += `*💡 Neue Content-Chancen (${newOpportunities.length}):*\n`;
  for (const o of topOpportunities) {
    const topic = (o.topic ?? o.keyword ?? o.title ?? 'Unbekannt').substring(0, 45);
    report += `• ${topic}\n`;
  }
  report += `\n`;
}

// Empfehlung
report += `*📌 Fokus nächste Woche:*\n`;
if (bottleneck) {
  report += `• Stage "${bottleneck[0]}" debuggen (${bottleneck[1]} Fehler)\n`;
}
if (piecesThisWeek.length < 3) {
  report += `• Content-Produktion hochfahren (Ziel: 5+ Pieces/Woche)\n`;
}
if (newOpportunities.length > 0) {
  const bestOpportunity = topOpportunities[0];
  const topic = (bestOpportunity?.topic ?? bestOpportunity?.keyword ?? 'Trend-Thema').substring(0, 40);
  report += `• Beste Chance: "${topic}" aufgreifen\n`;
}
if (!bottleneck && piecesThisWeek.length >= 3 && newOpportunities.length === 0) {
  report += `• Alles im grünen Bereich — weiter so! 🚀\n`;
}

return [{ json: { report } }];
